window.TWILIGHT_AUDIO_23={"version":1,"voice":"mn-MN-YesuiNeural","provider":"Microsoft Edge TTS","clientVersion":"7.3.1","synthetic":true,"scenes":{"tw23-001":["4fe47439b52037026a9fb1b2","cc0629c463fe8f226015513c","d90c701d26558667336298e4"],"tw23-002":["aca121d6d104b944716263c4","3ceb45e98039e4ab507d6473","d3a6164025b19785a7d7293c"],"tw23-003":["c9ba9d2f611c88956d1acd7b","976ec9df528dcc7d394200a2","5a6b4973514d5b215183754c"],"tw23-004":["fe5154a979de3b18ce8dcb1f","7a7a9a8d5a0d604a59cf17e5","f5fa0398e5347089f44695ad"],"tw23-005":["04e22b0c47f019cab5705f95","0157c678d2c8dbb517cc0d02","3ebbf9f02712d956f284355c"],"tw23-006":["41da03f3bb9c1b2f4232a839","d7e9fa392364776eed73ac7a","24fb922b0007cd22c6676296"],"tw23-007":["bbe23f590838f43b1a8f5810","277f6da24c26ed5740394cdc","157f43ae854b49ad19dffd80"],"tw23-008":["040b31ed8cd6cefa2964d334","65350aa6977f2a5f1fa81b24","71aecd6faa51cf110ef3634e"],"tw23-009":["e8e511a19a46c432126dd6e2","8e152034bed91ea714eebd68","fefb03c25726e8e25724d385"],"tw23-010":["6dcf61058d69cecea19717a9","d7d7514172c46dff47aa4abf","8294023376969352f5dfccda"],"tw23-011":["9ce9d86d90609baa01e39f9f","b5be3f0aec09aca73111f36b","2c4e5fc9dab1053934405e4d"],"tw23-012":["65bfef6fe4831818c7814c6c","45a40273b6b9205840acc909","a4421a184e90d36132ec2581"]},"clips":{"4fe47439b52037026a9fb1b2":{"text":"Би нүдээ тас анин хэвтээд зүүдэнд умбав. Гүн хар усанд хөвөхөд хүсэж залбирдаг гэрэлтэй дуу сонсдоно. Тэр хэрцгий ч үзэсгэлэнтэй, сэтгэл сэргээнэ. Бас илүү гүн, зэрлэг ууртай архираан гарав. Би доошилж газарт ойртоход тулсан гарын шарх хатгууллаа. Гэвч ирсэн зам руу эргэж харахад хэт дээр байв. Дараа нь үхснээ мэдэв. Цэнхэр усанд живэх зуур сахиусан тэнгэр миний нэрийг дуудах шиг байлаа. Тэр миний ганц хүслэн.","duration":28.536,"cues":[{"text":"Би нүдээ тас анин хэвтээд зүүдэнд умбав.","start":0.175,"end":3.2375},{"text":"Гүн хар усанд хөвөхөд хүсэж залбирдаг гэрэлтэй дуу сонсдоно.","start":3.2375,"end":7.1375},{"text":"Тэр хэрцгий ч үзэсгэлэнтэй, сэтгэл сэргээнэ.","start":7.1375,"end":10.1375},{"text":"Бас илүү гүн, зэрлэг ууртай архираан гарав.","start":10.1375,"end":13.2125},{"text":"Би доошилж газарт ойртоход тулсан гарын шарх хатгууллаа.","start":13.2125,"end":16.925},{"text":"Гэвч ирсэн зам руу эргэж харахад хэт дээр байв.","start":16.925,"end":20.1125},{"text":"Дараа нь үхснээ мэдэв.","start":20.1125,"end":22.125},{"text":"Цэнхэр усанд живэх зуур сахиусан тэнгэр миний нэрийг дуудах шиг байлаа.","start":22.125,"end":26.475},{"text":"Тэр миний ганц хүслэн.","start":26.475,"end":28.536}],"src":"4fe47439b52037026a9fb1b2.mp3","sha256":"58a310f81e9bd3d54949492ccb81540eef37b4d6b9138f9f613cba3ed240b735","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"b7b6f83214f82ae8d04f0b771f9abc7de366317626eefa3c2929096f6c01c780","method":"FFmpeg libmp3lame; original provider timing retained"}},"cc0629c463fe8f226015513c":{"text":"Нүдээ тас анин хэвтэхдээ би зүүдэнд умбав. Гүн харанхуй усанд хөвөн, залбирч хүсдэг гэрэлтэй дууг сонсоно. Тэр хэрцгий мөртөө үзэсгэлэн төгс, сэтгэл сэргээмээр. Бас илүү гүн, зэрлэг уур дүүрэн өөр архираан сонсдов. Би доошилсоор газарт ойртоход тулсан гарын зүссэн шарх хатгуулан өвдөв. Гэвч ирсэн зам руугаа эргэж харж чадамгүй тэртээ дээр байлаа. Дараа нь үхснээ мэдэв. Учир нь гүн цэнхэр усанд живэхдээ сахиусан тэнгэр миний нэрийг, миний ганц хүслэн намайг дуудах шиг сонсдсон юм.","duration":31.296,"cues":[{"text":"Нүдээ тас анин хэвтэхдээ би зүүдэнд умбав.","start":0.175,"end":3.3375},{"text":"Гүн харанхуй усанд хөвөн, залбирч хүсдэг гэрэлтэй дууг сонсоно.","start":3.3375,"end":7.35},{"text":"Тэр хэрцгий мөртөө үзэсгэлэн төгс, сэтгэл сэргээмээр.","start":7.35,"end":10.8875},{"text":"Бас илүү гүн, зэрлэг уур дүүрэн өөр архираан сонсдов.","start":10.8875,"end":14.55},{"text":"Би доошилсоор газарт ойртоход тулсан гарын зүссэн шарх хатгуулан өвдөв.","start":14.55,"end":18.9875},{"text":"Гэвч ирсэн зам руугаа эргэж харж чадамгүй тэртээ дээр байлаа.","start":18.9875,"end":22.875},{"text":"Дараа нь үхснээ мэдэв.","start":22.875,"end":24.8875},{"text":"Учир нь гүн цэнхэр усанд живэхдээ сахиусан тэнгэр миний нэрийг, миний ганц хүслэн намайг дуудах шиг сонсдсон юм.","start":24.8875,"end":31.296}],"src":"cc0629c463fe8f226015513c.mp3","sha256":"0ce480a7ffc634a60a576579884217a881aea80b8e150cad09b6f53b1465225f","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"1c499e97eff4c3cc4ddc3c2e86f796418c2a0bc2dfaabe4d8df3f44b1462a30d","method":"FFmpeg libmp3lame; original provider timing retained"}},"aca121d6d104b944716263c4":{"text":"«Үгүй, Бэлла минь, үгүй байлгүй» гэж сахиусан тэнгэр уйлав. Ард нь тэмцэл, үзэн ядсан архираан, урж тасдах аймшигтай дуу гарав. Гаслах мэт болоод гэнэт чимээгүй болов. Би түүний дууг ялгахыг хичээв. «Бэлла, гуйя! Намайг сонсож байна уу?» гэж тэр гуйна. Би юу ч болов хариулмаар ч уруулаа мэдрэхгүй байлаа. Тэр «Карлаил!» гэж орилов. Төгс хоолойд нь тарчлал байв. «Бэлла, үгүй, үгүй байлгүй» гэж давтлаа.","duration":29.4,"cues":[{"text":"«Үгүй, Бэлла минь, үгүй байлгүй» гэж сахиусан тэнгэр уйлав.","start":0.1875,"end":4.025},{"text":"Ард нь тэмцэл, үзэн ядсан архираан, урж тасдах аймшигтай дуу гарав.","start":4.025,"end":8.3125},{"text":"Гаслах мэт болоод гэнэт чимээгүй болов.","start":8.3125,"end":11.2625},{"text":"Би түүний дууг ялгахыг хичээв.","start":11.2625,"end":13.7125},{"text":"«Бэлла, гуйя!","start":13.7125,"end":15.45},{"text":"Намайг сонсож байна уу?»","start":15.45,"end":16.575},{"text":"гэж тэр гуйна.","start":16.575,"end":18.2125},{"text":"Би юу ч болов хариулмаар ч уруулаа мэдрэхгүй байлаа.","start":18.2125,"end":21.625},{"text":"Тэр «Карлаил!»","start":21.625,"end":22.3875},{"text":"гэж орилов.","start":22.3875,"end":23.9},{"text":"Төгс хоолойд нь тарчлал байв.","start":23.9,"end":26.3375},{"text":"«Бэлла, үгүй, үгүй байлгүй» гэж давтлаа.","start":26.3375,"end":29.4}],"src":"aca121d6d104b944716263c4.mp3","sha256":"d6fddb72f356838805e85d8f66eef1ed50a1c80557658cbe218fba07052f1a43","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"08871b7e1a1b93134181393fee0e7f7c19e553671003f26ee2c55e2d966b583b","method":"FFmpeg libmp3lame; original provider timing retained"}},"3ceb45e98039e4ab507d6473":{"text":"«Өө үгүй, Бэлла минь, үгүй байлгүй» гэж сахиусан тэнгэр уйлан гашуудав. Ард нь толгой эргэм тэмцлийн чимээ, үзэн ядсан битүү архираан, жихүүдэс хүрэм урж тасдах дуу сонсдов. Гаслах шиг болоод гэнэт таг чимээгүй болов. Би сахиусан тэнгэрийн дууг ялгахаар хүчлэв. «Бэлла, гуйя! Намайг сонсч байна уу, Бэлла? Арай ч дээ, гуйж байна, Бэлла, гуйя!» гэж тэр гуйна. Юу ч болов хариу хэлмээр байсан ч уруулаа мэдрэхгүй байлаа. «Карлаил!» гэж тэр тарчлан орилоод дахин «Бэлла, үгүй, даанч дээ, үгүй байлгүй» гэв.","duration":33.24,"cues":[{"text":"«Өө үгүй, Бэлла минь, үгүй байлгүй» гэж сахиусан тэнгэр уйлан гашуудав.","start":0.1875,"end":4.7},{"text":"Ард нь толгой эргэм тэмцлийн чимээ, үзэн ядсан битүү архираан, жихүүдэс хүрэм урж тасдах дуу сонсдов.","start":4.7,"end":10.5625},{"text":"Гаслах шиг болоод гэнэт таг чимээгүй болов.","start":10.5625,"end":13.675},{"text":"Би сахиусан тэнгэрийн дууг ялгахаар хүчлэв.","start":13.675,"end":16.675},{"text":"«Бэлла, гуйя!","start":16.675,"end":18.4125},{"text":"Намайг сонсч байна уу, Бэлла?","start":18.4125,"end":20.8},{"text":"Арай ч дээ, гуйж байна, Бэлла, гуйя!»","start":20.8,"end":22.775},{"text":"гэж тэр гуйна.","start":22.775,"end":24.325},{"text":"Юу ч болов хариу хэлмээр байсан ч уруулаа мэдрэхгүй байлаа.","start":24.325,"end":28.125},{"text":"«Карлаил!»","start":28.125,"end":28.6375},{"text":"гэж тэр тарчлан орилоод дахин «Бэлла, үгүй, даанч дээ, үгүй байлгүй» гэв.","start":28.6375,"end":33.24}],"src":"3ceb45e98039e4ab507d6473.mp3","sha256":"71553fb2a13450f9179a44ff69d8add7e30dcab7b88906005fbd90bd40487a2a","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"bb079eeb26ec98c419d154aef77dd86658f326ec2a24903c5d9060bd829cf1ca","method":"FFmpeg libmp3lame; original provider timing retained"}},"d90c701d26558667336298e4":{"text":"Нүдээ тас анин хэвтэхдээ би зүүд мөрөөдөлд умбав. Хөвсөлзөж байна, гүн харанхуй усан дотор, энэ зуур миний залбиран хүсэх гэрэл гэгээ татуулсан дуу хоолой сонсдоно – хэрцгий тэгсэн мөртөө үзэсгэлэн төгс бас дээр нь сэтгэл сэргэмээр. Энэ бол өөр нэгэн архираан, илүү гүн, илүү зэрлэг уур омог дүүрэн хүржигнэх дуу. Би доошилсоор, газарт бараг тулж ирэв, зүссэн шарх тулсан гарыг минь хатгуулан өвтгөлөө, гэлээ ч би ирсэн замаа эргэн харж чадамгүй тэртээ дээр аж. Дараа нь үхснээ мэдсэн юм. Учир нь, гүн цэнхэр усанд живж явахдаа, сахиусан тэнгэрийн дуу миний нэрийг хэлэх шиг, миний цорын ганц хүслэн дуудах шиг.","duration":35.28,"cues":[{"text":"Нүдээ тас анин хэвтэхдээ би зүүд мөрөөдөлд умбав.","start":0.175,"end":3.625},{"text":"Хөвсөлзөж байна, гүн харанхуй усан дотор, энэ зуур миний залбиран хүсэх гэрэл гэгээ татуулсан дуу хоолой сонсдоно – хэрцгий тэгсэн мөртөө үзэсгэлэн төгс бас дээр нь сэтгэл сэргэмээр.","start":3.625,"end":13.3625},{"text":"Энэ бол өөр нэгэн архираан, илүү гүн, илүү зэрлэг уур омог дүүрэн хүржигнэх дуу.","start":13.3625,"end":18.425},{"text":"Би доошилсоор, газарт бараг тулж ирэв, зүссэн шарх тулсан гарыг минь хатгуулан өвтгөлөө, гэлээ ч би ирсэн замаа эргэн харж чадамгүй тэртээ дээр аж.","start":18.425,"end":26.4625},{"text":"Дараа нь үхснээ мэдсэн юм.","start":26.4625,"end":28.6875},{"text":"Учир нь, гүн цэнхэр усанд живж явахдаа, сахиусан тэнгэрийн дуу миний нэрийг хэлэх шиг, миний цорын ганц хүслэн дуудах шиг.","start":28.6875,"end":35.28}],"src":"d90c701d26558667336298e4.mp3","sha256":"8f9f7c52080c3cafb5ba4c6b0574c2861f0f246899f8d032fd165efaf71d6c1a","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"978f3f8555d0b4cf230e6e0faca7fbab6ad4879e5378718b31a13c8a112b8448","method":"FFmpeg libmp3lame; original provider timing retained"}},"d3a6164025b19785a7d7293c":{"text":"“Өө үгүй ээ, Бэлла минь, үгүй байлгүй” сахиусан тэнгэр уйлан халина. Гашуудан уйлах дуу хоолойн ард өөр нэгэн чимээ – толгой эргэм үймэлдэн тэмцэх дуу. Үзэн ядсан битүү архираан, жихүүдэс хүрэм урж тасдах дуу, тэгснээ гаслаад явчих шиг, гэнэт таг чимээгүй болчлоо. Би сахиусан тэнгэрийн дууг ялгаж сонсохын тулд хүчлэв. “Бэлла гуйя! Бэлла, намайг сонсч байна уу, арай ч дээ, гуйж байна, Бэлла, гуйя!” тэр гуйн мөргөнө. Би хариу хэлмээр байлаа. Юу ч хамаагүй. Гэвч уруулаа үл мэдрэнэ. “Карлаил!” хэмээн сахиус орилон дуудав, түүний төгс дуу хоолойнд тарчлан зовлон мэдрэгдэнэ. “Бэлла, Бэлла, үгүй, даанч дээ, үгүй байлгүй дээ.”","duration":41.112,"cues":[{"text":"“Өө үгүй ээ, Бэлла минь, үгүй байлгүй” сахиусан тэнгэр уйлан халина.","start":0.1875,"end":4.4875},{"text":"Гашуудан уйлах дуу хоолойн ард өөр нэгэн чимээ – толгой эргэм үймэлдэн тэмцэх дуу.","start":4.4875,"end":9.55},{"text":"Үзэн ядсан битүү архираан, жихүүдэс хүрэм урж тасдах дуу, тэгснээ гаслаад явчих шиг, гэнэт таг чимээгүй болчлоо.","start":9.55,"end":15.9375},{"text":"Би сахиусан тэнгэрийн дууг ялгаж сонсохын тулд хүчлэв.","start":15.9375,"end":19.475},{"text":"“Бэлла гуйя!","start":19.475,"end":21.05},{"text":"Бэлла, намайг сонсч байна уу, арай ч дээ, гуйж байна, Бэлла, гуйя!”","start":21.05,"end":24.4125},{"text":"тэр гуйн мөргөнө.","start":24.4125,"end":26.0625},{"text":"Би хариу хэлмээр байлаа.","start":26.0625,"end":28.2375},{"text":"Юу ч хамаагүй.","start":28.2375,"end":29.925},{"text":"Гэвч уруулаа үл мэдрэнэ.","start":29.925,"end":32.2125},{"text":"“Карлаил!”","start":32.2125,"end":32.725},{"text":"хэмээн сахиус орилон дуудав, түүний төгс дуу хоолойнд тарчлан зовлон мэдрэгдэнэ.","start":32.725,"end":37.6},{"text":"“Бэлла, Бэлла, үгүй, даанч дээ, үгүй байлгүй дээ.”","start":37.6,"end":41.112}],"src":"d3a6164025b19785a7d7293c.mp3","sha256":"a6dfbfecbfadec93c081a51e57e6fa441b8f3a21c7366c4e432ef9963315d7bd","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"6ba891aa1e8557e82927e48f5be990815e518c7afa6277aeaa810ef7044b8f4e","method":"FFmpeg libmp3lame; original provider timing retained"}},"976ec9df528dcc7d394200a2":{"text":"Тэр мэгшин цурхирсаар байв. Сахиусан тэнгэр уйлдаггүй, ингэж болохгүй. Харж чадвал бүх юм зүгээр гэж хэлэхсэн. Гэвч ус дэндүү гүн, намайг доош татаж, амьсгалж үл чадна. Дагз даган хүчтэй өвдөж эхлэв. Өвдөлт харанхуйг гэтэлж намайг олоод, бусад бүр хүчтэй өвдөлт нэмэгдлээ. Би амьсгаа давхцан тийчилж, хар усыг хага ярах мэт чарлав. Сахиусан тэнгэр «Белла!» гэж орь дуу тавьсаар байлаа. Нам дуу цус их алдсан ч толгойн шарх гүн биш гээд хугарсан хөлийг болгоомжлохыг хэлэв.","duration":31.896,"cues":[{"text":"Тэр мэгшин цурхирсаар байв.","start":0.175,"end":2.425},{"text":"Сахиусан тэнгэр уйлдаггүй, ингэж болохгүй.","start":2.425,"end":5.55},{"text":"Харж чадвал бүх юм зүгээр гэж хэлэхсэн.","start":5.55,"end":8.525},{"text":"Гэвч ус дэндүү гүн, намайг доош татаж, амьсгалж үл чадна.","start":8.525,"end":12.3875},{"text":"Дагз даган хүчтэй өвдөж эхлэв.","start":12.3875,"end":14.9875},{"text":"Өвдөлт харанхуйг гэтэлж намайг олоод, бусад бүр хүчтэй өвдөлт нэмэгдлээ.","start":14.9875,"end":19.4875},{"text":"Би амьсгаа давхцан тийчилж, хар усыг хага ярах мэт чарлав.","start":19.4875,"end":23.225},{"text":"Сахиусан тэнгэр «Белла!»","start":23.225,"end":24.4625},{"text":"гэж орь дуу тавьсаар байлаа.","start":24.4625,"end":26.7125},{"text":"Нам дуу цус их алдсан ч толгойн шарх гүн биш гээд хугарсан хөлийг болгоомжлохыг хэлэв.","start":26.7125,"end":31.896}],"src":"976ec9df528dcc7d394200a2.mp3","sha256":"fe4492f4e92163ce1ac2f5e7dcef17ae940eab4487dc34b042710a80cd24b3e6","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"cb1e4222db6ac19cfbef9db750dee56b46884de0b06f9399392461258ccd0b80","method":"FFmpeg libmp3lame; original provider timing retained"}},"5a6b4973514d5b215183754c":{"text":"хэмээн мэгшин гингнэж, цурхирсаар. Сахиусан тэнгэр уйлдаггүй юм, тэгэж болохгүй. Би түүнийг харвал, бүхнийг зүгээр гэдгээ хэлнэ, гэвч ус хэтэрхий гүнзгий, намайг улам бүр доош чангааж, би амьсгалж үл чадна. Ар дагз даган өвчин орчихож. Их өвтгөж байна. Энэ өвчин харанхуйг гэтлэн намайг олж ирсэн шиг, бусад нь ч бас нэмэрлэв , илүү хүчтэй өвдөлтүүд. Тэсвэр алдаж амьсгаа давхцан тийчилсээр, гүн хар усыг хага яран чарлав. “Бэлла” сахиусан тэнгэр орь дуу тавьсаар. “Цус их алдаж, гэхдээ тархиндаа авсан шарх нь гүн биш юм” гэх намуухан дуу надад сонсогдов. “Хөлийг нь болгоомжтой, хугарсан байна.”","duration":38.76,"cues":[{"text":"хэмээн мэгшин гингнэж, цурхирсаар.","start":0.175,"end":2.925},{"text":"Сахиусан тэнгэр уйлдаггүй юм, тэгэж болохгүй.","start":2.925,"end":6.175},{"text":"Би түүнийг харвал, бүхнийг зүгээр гэдгээ хэлнэ, гэвч ус хэтэрхий гүнзгий, намайг улам бүр доош чангааж, би амьсгалж үл чадна.","start":6.175,"end":13.1875},{"text":"Ар дагз даган өвчин орчихож.","start":13.1875,"end":15.7375},{"text":"Их өвтгөж байна.","start":15.7375,"end":17.5125},{"text":"Энэ өвчин харанхуйг гэтлэн намайг олж ирсэн шиг, бусад нь ч бас нэмэрлэв , илүү хүчтэй өвдөлтүүд.","start":17.5125,"end":23.1875},{"text":"Тэсвэр алдаж амьсгаа давхцан тийчилсээр, гүн хар усыг хага яран чарлав.","start":23.1875,"end":27.6875},{"text":"“Бэлла” сахиусан тэнгэр орь дуу тавьсаар.","start":27.6875,"end":30.6375},{"text":"“Цус их алдаж, гэхдээ тархиндаа авсан шарх нь гүн биш юм” гэх намуухан дуу надад сонсогдов.","start":30.6375,"end":36.025},{"text":"“Хөлийг нь болгоомжтой, хугарсан байна.”","start":36.025,"end":38.76}],"src":"5a6b4973514d5b215183754c.mp3","sha256":"6ebc01d3296efef370b7531b40112da4c1ef3fa2166c58b476534613dc8a1121","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"5907d20dafa75baeb83ef57c16507becf9c6986c3914702318625a03aa456473","method":"FFmpeg libmp3lame; original provider timing retained"}},"c9ba9d2f611c88956d1acd7b":{"text":"Тэр мэгшин уйлсаар байв. Сахиусан тэнгэр уйлдаггүй, уйлж болохгүй. Би түүнийг харвал бүх юм зүгээр гэж хэлнэ. Гэвч ус гүн, намайг доош татаж, би амьсгалж чадахгүй байлаа. Дагз хүчтэй өвдөв. Өвдөлт харанхуйг нэвт олж ирсэн мэт, өөр илүү хүчтэй өвдөлт нэмэгдэнэ. Би амьсгаа давхцан тийчилж, хар усыг хагалах мэт чарлав. Сахиусан тэнгэр «Белла!» гэж орилсоор байв. Нам дуу цус их алдсан ч толгойн шарх гүн биш гэв. Хөл хугарсан тул болгоомжтой гэв.","duration":31.848,"cues":[{"text":"Тэр мэгшин уйлсаар байв.","start":0.175,"end":2.325},{"text":"Сахиусан тэнгэр уйлдаггүй, уйлж болохгүй.","start":2.325,"end":5.475},{"text":"Би түүнийг харвал бүх юм зүгээр гэж хэлнэ.","start":5.475,"end":8.425},{"text":"Гэвч ус гүн, намайг доош татаж, би амьсгалж чадахгүй байлаа.","start":8.425,"end":12.375},{"text":"Дагз хүчтэй өвдөв.","start":12.375,"end":14.4},{"text":"Өвдөлт харанхуйг нэвт олж ирсэн мэт, өөр илүү хүчтэй өвдөлт нэмэгдэнэ.","start":14.4,"end":18.9},{"text":"Би амьсгаа давхцан тийчилж, хар усыг хагалах мэт чарлав.","start":18.9,"end":22.55},{"text":"Сахиусан тэнгэр «Белла!»","start":22.55,"end":23.85},{"text":"гэж орилсоор байв.","start":23.85,"end":25.65},{"text":"Нам дуу цус их алдсан ч толгойн шарх гүн биш гэв.","start":25.65,"end":29.1375},{"text":"Хөл хугарсан тул болгоомжтой гэв.","start":29.1375,"end":31.848}],"src":"c9ba9d2f611c88956d1acd7b.mp3","sha256":"bec45f170c7116397fbebf1ca89fc229244c4d43b6f9625fa55969b76be47189","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"2470227215933e821560175822dc24c8fad634ba07de395b0f6931fa7b4d1f90","method":"FFmpeg libmp3lame; original provider timing retained"}},"fe5154a979de3b18ce8dcb1f":{"text":"Би уурлан гаслах сахиусан тэнгэрийн чичрэх уруулыг харах шиг болов. Гүн зүссэн шарх мэдрэгдэнэ. Диваажин ийм их өвддөг гэж үү? Дуу хэдэн хавирга бас хугарсан бололтой гэв. Зүсэлтийн өвдөлт намдахад шинэ өвдөлт ирлээ. Гар түлэгдэх мэт өвдөж, бүх биеийг хучив. Хэн нэгэн намайг түлж байгаа мэт. Эдвардыг дуудахыг хүссэн ч дуу гарсангүй, учрыг бодох ч сөхөөгүй. «Удахгүй зүгээр болно. Намайг сонсож байна уу? Би чамд хайртай» гэж тэр хэлэв.","duration":31.656,"cues":[{"text":"Би уурлан гаслах сахиусан тэнгэрийн чичрэх уруулыг харах шиг болов.","start":0.175,"end":4.25},{"text":"Гүн зүссэн шарх мэдрэгдэнэ.","start":4.25,"end":6.5875},{"text":"Диваажин ийм их өвддөг гэж үү?","start":6.5875,"end":9.25},{"text":"Дуу хэдэн хавирга бас хугарсан бололтой гэв.","start":9.25,"end":12.35},{"text":"Зүсэлтийн өвдөлт намдахад шинэ өвдөлт ирлээ.","start":12.35,"end":15.3625},{"text":"Гар түлэгдэх мэт өвдөж, бүх биеийг хучив.","start":15.3625,"end":18.35},{"text":"Хэн нэгэн намайг түлж байгаа мэт.","start":18.35,"end":20.825},{"text":"Эдвардыг дуудахыг хүссэн ч дуу гарсангүй, учрыг бодох ч сөхөөгүй.","start":20.825,"end":25.125},{"text":"«Удахгүй зүгээр болно.","start":25.125,"end":27.2125},{"text":"Намайг сонсож байна уу?","start":27.2125,"end":29.225},{"text":"Би чамд хайртай» гэж тэр хэлэв.","start":29.225,"end":31.656}],"src":"fe5154a979de3b18ce8dcb1f.mp3","sha256":"8f6262470482b05cfb8b2f9b6380d2846142a781ee65c84d305a07ae831cb663","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"fd04992ae792c58e7c567aedfcb49f09acae7a145165724f5f34e87556c61f6a","method":"FFmpeg libmp3lame; original provider timing retained"}},"f5fa0398e5347089f44695ad":{"text":"Багтаж ядсан уур хилэнгээр гаслах сахиусан тэнгэрийн чичигнэх уруул үзэгдэх шиг. Надад үзүүрт мэсний гүн орсон шарх мэдрэгдэв. Энэ диваажин мөн гэж үү, ийм байдаг гэж үү? Ямар их өвчин зовиуртай юм бэ? “Хэдэн хавирга бас хугарсан бололтой” үзлэг хийх дуу үргэлжилсээр. Гүн зүссэн шархны өвдөлт аажим дарагдаж оронд нь шинэ өвчин үүслээ, гар зумлан шалзлах мэт хүчтэй өвдөлт бүх биеийг хучлаа. Хэн нэгэн намайг түлж байх шиг. “Эдвард” би түүнд хэлмээр байсан ч дуу гарч өгсөнгүй. Яагаад байгаагаа ч ухаарах сөхөөгүй байв. “Бэлла, удахгүй зүгээр болно оо. Намайг сонсч байна уу, Бэлла? Би чамд хайртай.”","duration":40.68,"cues":[{"text":"Багтаж ядсан уур хилэнгээр гаслах сахиусан тэнгэрийн чичигнэх уруул үзэгдэх шиг.","start":0.175,"end":4.975},{"text":"Надад үзүүрт мэсний гүн орсон шарх мэдрэгдэв.","start":4.975,"end":8.3375},{"text":"Энэ диваажин мөн гэж үү, ийм байдаг гэж үү?","start":8.3375,"end":11.525},{"text":"Ямар их өвчин зовиуртай юм бэ?","start":11.525,"end":14.05},{"text":"“Хэдэн хавирга бас хугарсан бололтой” үзлэг хийх дуу үргэлжилсээр.","start":14.05,"end":18.15},{"text":"Гүн зүссэн шархны өвдөлт аажим дарагдаж оронд нь шинэ өвчин үүслээ, гар зумлан шалзлах мэт хүчтэй өвдөлт бүх биеийг хучлаа.","start":18.15,"end":25.2875},{"text":"Хэн нэгэн намайг түлж байх шиг.","start":25.2875,"end":27.65},{"text":"“Эдвард” би түүнд хэлмээр байсан ч дуу гарч өгсөнгүй.","start":27.65,"end":31.1375},{"text":"Яагаад байгаагаа ч ухаарах сөхөөгүй байв.","start":31.1375,"end":33.975},{"text":"“Бэлла, удахгүй зүгээр болно оо.","start":33.975,"end":36.525},{"text":"Намайг сонсч байна уу, Бэлла?","start":36.525,"end":38.9125},{"text":"Би чамд хайртай.”","start":38.9125,"end":40.68}],"src":"f5fa0398e5347089f44695ad.mp3","sha256":"fdc25a09489f1a2aadad8b9f34508ed9501c5505264bba26932b120c2acc5abb","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"0df8e8c813097fcc6b01e9f8ddf35142eb7bc205845c83785e8e322cddddf53e","method":"FFmpeg libmp3lame; original provider timing retained"}},"7a7a9a8d5a0d604a59cf17e5":{"text":"Уур хилэнгээр гаслах сахиусан тэнгэрийн чичрэх уруул үзэгдэх шиг болов. Мэсний гүн орсон шарх мэдрэгдэнэ. Диваажин ийм байдаг гэж үү, яагаад ийм их өвддөг юм бэ? Үзлэгийн дуу хэдэн хавирга бас хугарсан бололтой гэв. Гүн зүсэлтийн өвдөлт намдаж, оронд нь гар зумлан шалзлах мэт хүчтэй шинэ өвдөлт бүх биеийг хучлаа. Намайг хэн нэгэн түлэх шиг. Эдвардыг дуудахыг хүссэн ч дуу гарсангүй, учрыг ч ухаарах сөхөөгүй байв. «Удахгүй зүгээр болно. Намайг сонсч байна уу, Бэлла? Би чамд хайртай» гэв.","duration":33.456,"cues":[{"text":"Уур хилэнгээр гаслах сахиусан тэнгэрийн чичрэх уруул үзэгдэх шиг болов.","start":0.175,"end":4.5125},{"text":"Мэсний гүн орсон шарх мэдрэгдэнэ.","start":4.5125,"end":7.2125},{"text":"Диваажин ийм байдаг гэж үү, яагаад ийм их өвддөг юм бэ?","start":7.2125,"end":11.0375},{"text":"Үзлэгийн дуу хэдэн хавирга бас хугарсан бололтой гэв.","start":11.0375,"end":14.5},{"text":"Гүн зүсэлтийн өвдөлт намдаж, оронд нь гар зумлан шалзлах мэт хүчтэй шинэ өвдөлт бүх биеийг хучлаа.","start":14.5,"end":20.325},{"text":"Намайг хэн нэгэн түлэх шиг.","start":20.325,"end":22.5125},{"text":"Эдвардыг дуудахыг хүссэн ч дуу гарсангүй, учрыг ч ухаарах сөхөөгүй байв.","start":22.5125,"end":27.025},{"text":"«Удахгүй зүгээр болно.","start":27.025,"end":29.1125},{"text":"Намайг сонсч байна уу, Бэлла?","start":29.1125,"end":31.5},{"text":"Би чамд хайртай» гэв.","start":31.5,"end":33.456}],"src":"7a7a9a8d5a0d604a59cf17e5.mp3","sha256":"6f5689986ddcdd005e63b2427d4e3671df641ce37a2fc243de2d03654e2d68ee","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"72c9d2cc39982295675ebb77acbcd7ab079206716dc43ca8c85b198c3fd4b332","method":"FFmpeg libmp3lame; original provider timing retained"}},"04e22b0c47f019cab5705f95":{"text":"Би дахин Эдвардыг дуудахад сул дуу гарлаа. Тэр дэргэд байна гэв. Өвдөж байгаагаа хэлэхэд мэдэж байна гээд цухалдан өндийж, юм хийгээч гэв. Карлаил цүнхээ бушуу авчрахыг хүсээд Алис амьсгаагаа тэвчвэл дээр гэв. Би Алисыг дуудлаа. Тэр энд, намайг олох газрыг хэлсэн гэнэ. Гар шатаж байна гэж чарлав. Би бүрэн сэргэж нүдээ нээсэн ч бараан үүл халхлах мэт түүний царай харагдахгүй байв. Галыг яагаад унтраахгүй вэ? Тэр айсан дуугаар намайг дуудлаа.","duration":31.32,"cues":[{"text":"Би дахин Эдвардыг дуудахад сул дуу гарлаа.","start":0.175,"end":3.3375},{"text":"Тэр дэргэд байна гэв.","start":3.3375,"end":5.275},{"text":"Өвдөж байгаагаа хэлэхэд мэдэж байна гээд цухалдан өндийж, юм хийгээч гэв.","start":5.275,"end":9.725},{"text":"Карлаил цүнхээ бушуу авчрахыг хүсээд Алис амьсгаагаа тэвчвэл дээр гэв.","start":9.725,"end":14.1},{"text":"Би Алисыг дуудлаа.","start":14.1,"end":16.125},{"text":"Тэр энд, намайг олох газрыг хэлсэн гэнэ.","start":16.125,"end":19.1375},{"text":"Гар шатаж байна гэж чарлав.","start":19.1375,"end":21.3375},{"text":"Би бүрэн сэргэж нүдээ нээсэн ч бараан үүл халхлах мэт түүний царай харагдахгүй байв.","start":21.3375,"end":26.3875},{"text":"Галыг яагаад унтраахгүй вэ?","start":26.3875,"end":28.7625},{"text":"Тэр айсан дуугаар намайг дуудлаа.","start":28.7625,"end":31.32}],"src":"04e22b0c47f019cab5705f95.mp3","sha256":"54a2770bdb038393d9c91a4a6814246f5789436f4977d8ef4d63747f2256951a","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"0e82a77a53635aedffbfc564e540c410522594e462ad37ff15f6686a569a3400","method":"FFmpeg libmp3lame; original provider timing retained"}},"0157c678d2c8dbb517cc0d02":{"text":"Би Эдвардыг ахин дуудах гэж хүчлээд энэ удаа сул дуу гаргав. Тэр дэргэд байна гэв. Би өвдөөд байна гэж гонгинов. Эдвард мэдэж байна гээд цухалдан өндийж, ямар нэг юм хийгээч гэв. Карлаил цүнхээ бушуу авчрахыг хүсээд Алис амьсгаагаа тэвчвэл дээр гэж анхааруулав. Би Алисыг ёолон дуудав. Тэр энд байгаа, намайг хаанаас олохыг хэлсэн гэнэ. Гар шатаж байна гэж чарлаад харанхуйгаас бүрэн сэргэж нүдээ нээв. Гэвч бараан үүл тогтсон мэт түүний царай харагдахгүй. Яагаад хэн ч галыг унтраахгүй вэ? Тэр их айсан сонсогдож «Белла?» гэв.","duration":36.072,"cues":[{"text":"Би Эдвардыг ахин дуудах гэж хүчлээд энэ удаа сул дуу гаргав.","start":0.175,"end":4.0},{"text":"Тэр дэргэд байна гэв.","start":4.0,"end":5.9375},{"text":"Би өвдөөд байна гэж гонгинов.","start":5.9375,"end":8.375},{"text":"Эдвард мэдэж байна гээд цухалдан өндийж, ямар нэг юм хийгээч гэв.","start":8.375,"end":12.45},{"text":"Карлаил цүнхээ бушуу авчрахыг хүсээд Алис амьсгаагаа тэвчвэл дээр гэж анхааруулав.","start":12.45,"end":17.375},{"text":"Би Алисыг ёолон дуудав.","start":17.375,"end":19.65},{"text":"Тэр энд байгаа, намайг хаанаас олохыг хэлсэн гэнэ.","start":19.65,"end":22.95},{"text":"Гар шатаж байна гэж чарлаад харанхуйгаас бүрэн сэргэж нүдээ нээв.","start":22.95,"end":27.0625},{"text":"Гэвч бараан үүл тогтсон мэт түүний царай харагдахгүй.","start":27.0625,"end":30.6},{"text":"Яагаад хэн ч галыг унтраахгүй вэ?","start":30.6,"end":33.35},{"text":"Тэр их айсан сонсогдож «Белла?»","start":33.35,"end":34.975},{"text":"гэв.","start":34.975,"end":36.072}],"src":"0157c678d2c8dbb517cc0d02.mp3","sha256":"58b64f4b8be8009792eec535ba2eeac2b24e04a6f117dafc12580e4dcc17976d","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"d04378ba4415e86348b2bd9c1d32c1a09c575f7cd87f8becfe09e9898aa08e6d","method":"FFmpeg libmp3lame; original provider timing retained"}},"3ebbf9f02712d956f284355c":{"text":"“Эдвард,” би ахин нэг хүчлэв. Энэ удаа сулхан дуу гарлаа. “Би дэргэд чинь байна” “Өвдөөд байна.” хэмээн гонгинов. “Мэдэж байнаа, Бэлла, мэдэж байна” – цухалдан өндийж– “ямар нэг юм хийгээч дээ” гэв. “Миний цүнхийг, бушуул... Амьсгаагаа тэвч, Алис, тэр нь дээр,” Карлаил анхааруулав. “Алис?” ёолон дуу алдав. “Тэр энд байнаа, чамайг хаанаас олохыг хэлж өгсөн юм.” “Гар өвдөөд байна,” “Миний гар шатаж байна!” би чарлан харанхуйн дундаас бүрэн сэрж нүдээ нээтэл түүний минь царай харагдахгүй байлаа. Яг л бараан өнгийн үүл миний нүдэн дээр тогтсон юм шиг. Хэн нэгэн яагаад галыг унтрааж өгөхгүй байна аа? Тэр их айсан сонсдож байв. “Белла?”","duration":42.936,"cues":[{"text":"“Эдвард,” би ахин нэг хүчлэв.","start":0.175,"end":2.625},{"text":"Энэ удаа сулхан дуу гарлаа.","start":2.625,"end":5.0125},{"text":"“Би дэргэд чинь байна” “Өвдөөд байна.”","start":5.0125,"end":6.7875},{"text":"хэмээн гонгинов.","start":6.7875,"end":8.525},{"text":"“Мэдэж байнаа, Бэлла, мэдэж байна” – цухалдан өндийж– “ямар нэг юм хийгээч дээ” гэв.","start":8.525,"end":13.625},{"text":"“Миний цүнхийг, бушуул...","start":13.625,"end":15.6875},{"text":"Амьсгаагаа тэвч, Алис, тэр нь дээр,” Карлаил анхааруулав.","start":15.6875,"end":19.425},{"text":"“Алис?”","start":19.425,"end":19.8875},{"text":"ёолон дуу алдав.","start":19.8875,"end":21.8},{"text":"“Тэр энд байнаа, чамайг хаанаас олохыг хэлж өгсөн юм.”","start":21.8,"end":25.2375},{"text":"“Гар өвдөөд байна,” “Миний гар шатаж байна!”","start":25.2375,"end":27.25},{"text":"би чарлан харанхуйн дундаас бүрэн сэрж нүдээ нээтэл түүний минь царай харагдахгүй байлаа.","start":27.25,"end":32.45},{"text":"Яг л бараан өнгийн үүл миний нүдэн дээр тогтсон юм шиг.","start":32.45,"end":36.0375},{"text":"Хэн нэгэн яагаад галыг унтрааж өгөхгүй байна аа?","start":36.0375,"end":39.2875},{"text":"Тэр их айсан сонсдож байв.","start":39.2875,"end":41.5375},{"text":"“Белла?”","start":41.5375,"end":42.936}],"src":"3ebbf9f02712d956f284355c.mp3","sha256":"3241868ac11d674434b5e9cf097d19d38bd0d22046774787d8f1078f44561d5d","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"933986d847ee3a501cbdcf4724c9ea8bf61af3362a7c0a109600cbaf299e5e86","method":"FFmpeg libmp3lame; original provider timing retained"}},"d7e9fa392364776eed73ac7a":{"text":"Би гал унтраахыг орилон хүсэв. Эдвард Карлаилд гарыг харахыг хэлэхэд тэр цочирдон «Тэр Беллаг хазсан байна» гэв. Эдвард айсандаа амьсгаагаа хүчтэй сорлоо. Алис хажууд «Чи л хийхгүй бол болохгүй» гэж, хүйтэн хуруугаар нулимсыг минь арчив. Эдвард эсэргүүцэн үгүй гэв. Би Алисыг ёолон дуудлаа. Карлаил боломж байгаа гэхэд Эдвард гуйх мэт юу гэж асуув. «Хорыг буцааж сорох гээд үз. Шарх цэвэрхэн харагдаж байна» гэв. Түүнийг ярихад толгойд юм хатган татах мэдрэгдсэн ч шатах гарнаасаа болж тэр өвдөлтийг мэдрээгүй.","duration":34.824,"cues":[{"text":"Би гал унтраахыг орилон хүсэв.","start":0.175,"end":2.675},{"text":"Эдвард Карлаилд гарыг харахыг хэлэхэд тэр цочирдон «Тэр Беллаг хазсан байна» гэв.","start":2.675,"end":7.5125},{"text":"Эдвард айсандаа амьсгаагаа хүчтэй сорлоо.","start":7.5125,"end":10.5875},{"text":"Алис хажууд «Чи л хийхгүй бол болохгүй» гэж, хүйтэн хуруугаар нулимсыг минь арчив.","start":10.5875,"end":15.475},{"text":"Эдвард эсэргүүцэн үгүй гэв.","start":15.475,"end":17.9},{"text":"Би Алисыг ёолон дуудлаа.","start":17.9,"end":20.2625},{"text":"Карлаил боломж байгаа гэхэд Эдвард гуйх мэт юу гэж асуув.","start":20.2625,"end":24.1375},{"text":"«Хорыг буцааж сорох гээд үз.","start":24.1375,"end":26.575},{"text":"Шарх цэвэрхэн харагдаж байна» гэв.","start":26.575,"end":29.125},{"text":"Түүнийг ярихад толгойд юм хатган татах мэдрэгдсэн ч шатах гарнаасаа болж тэр өвдөлтийг мэдрээгүй.","start":29.125,"end":34.824}],"src":"d7e9fa392364776eed73ac7a.mp3","sha256":"c374d5b83bbf87f68100204530e004d84b59f6263a7ef23c49a5e008ee5e242d","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"94dc181ce3b99f9a0f3e212298e8c227868f5f84b49ba0b67e5a81d04bf4fbc5","method":"FFmpeg libmp3lame; original provider timing retained"}},"41da03f3bb9c1b2f4232a839":{"text":"Би галыг унтраа гэж орилов. Эдвард Карлаилд гарыг хар гэв. Карлаил цочирдон «Тэр Беллаг хазсан байна» гэлээ. Эдвард айж хүчтэй амьсгаа авав. Алис хажууд «Чи л хийх хэрэгтэй» гэж, хүйтэн хуруугаар нулимс арчив. Эдвард үгүй гэв. Би Алисыг дуудахад Карлаил боломж байгаа гэлээ. Эдвард юу гэж гуйсан мэт асуув. Хорыг буцаан сорох гээд үз, шарх цэвэрхэн байна гэв. Толгойд юм хатгаж татах ч шатах гарнаас болж тэр өвдөлтийг мэдрээгүй.","duration":30.936,"cues":[{"text":"Би галыг унтраа гэж орилов.","start":0.175,"end":2.65},{"text":"Эдвард Карлаилд гарыг хар гэв.","start":2.65,"end":5.25},{"text":"Карлаил цочирдон «Тэр Беллаг хазсан байна» гэлээ.","start":5.25,"end":8.5},{"text":"Эдвард айж хүчтэй амьсгаа авав.","start":8.5,"end":11.0375},{"text":"Алис хажууд «Чи л хийх хэрэгтэй» гэж, хүйтэн хуруугаар нулимс арчив.","start":11.0375,"end":15.2125},{"text":"Эдвард үгүй гэв.","start":15.2125,"end":17.1125},{"text":"Би Алисыг дуудахад Карлаил боломж байгаа гэлээ.","start":17.1125,"end":20.45},{"text":"Эдвард юу гэж гуйсан мэт асуув.","start":20.45,"end":23.025},{"text":"Хорыг буцаан сорох гээд үз, шарх цэвэрхэн байна гэв.","start":23.025,"end":26.5875},{"text":"Толгойд юм хатгаж татах ч шатах гарнаас болж тэр өвдөлтийг мэдрээгүй.","start":26.5875,"end":30.936}],"src":"41da03f3bb9c1b2f4232a839.mp3","sha256":"31e88b0d552f9f39ac6aba65361293d5c4eb5a623eecff07c1f0c545f0b22272","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"0022f4823cbbf82aaa53e0b8bbd6c955aa99123ae4598c7820b33b24437dea93","method":"FFmpeg libmp3lame; original provider timing retained"}},"24fb922b0007cd22c6676296":{"text":"“Гал! Хэн нэгэн унтраагаад өгөөч дээ!” би орлив. “Карлаил! Гарыг нь хар!” “Тэр Беллаг хазчихсан байна.” Карлаилийн цочирдсон хоолой гарав. Эдвардийн айсандаа болоод амьсгаагаа хүчтэй сорох нь сонсдлоо. “Эдвард чи л хийхгүй бол болохгүй.” Алисийн дуу хоолой миний хажууд сонсдож түүний хүйтэн хуруунууд нулимсыг минь арчиж өгч байлаа. “Үгүй!” Эдвард эсэргүүцэв. “Алис,” би ёолон дуудлаа. “Түүнд боломж байгаа,” Карлаил хэлэв. “Юу?” Эдвард түүнээс гуйсан янзтай асуув. “Чи хорыг нь буцаад сорох гээд үз. Шарх нь их цэвэрхэн харагдаж байна.” Карлаилийн дуу сонсдох зуур миний толгойнд юм хатган татах мэдрэгдсэн ч би шатаж байсан гарнаасаа болж өвдөлтийг мэдрээгүй юм.","duration":49.776,"cues":[{"text":"“Гал!","start":0.175,"end":1.3875},{"text":"Хэн нэгэн унтраагаад өгөөч дээ!”","start":1.3875,"end":3.0125},{"text":"би орлив.","start":3.0125,"end":4.425},{"text":"“Карлаил!","start":4.425,"end":5.8875},{"text":"Гарыг нь хар!”","start":5.8875,"end":7.4625},{"text":"“Тэр Беллаг хазчихсан байна.”","start":7.4625,"end":9.7375},{"text":"Карлаилийн цочирдсон хоолой гарав.","start":9.7375,"end":12.4625},{"text":"Эдвардийн айсандаа болоод амьсгаагаа хүчтэй сорох нь сонсдлоо.","start":12.4625,"end":16.45},{"text":"“Эдвард чи л хийхгүй бол болохгүй.”","start":16.45,"end":19.1375},{"text":"Алисийн дуу хоолой миний хажууд сонсдож түүний хүйтэн хуруунууд нулимсыг минь арчиж өгч байлаа.","start":19.1375,"end":24.825},{"text":"“Үгүй!”","start":24.825,"end":26.125},{"text":"Эдвард эсэргүүцэв.","start":26.125,"end":28.1},{"text":"“Алис,” би ёолон дуудлаа.","start":28.1,"end":30.45},{"text":"“Түүнд боломж байгаа,” Карлаил хэлэв.","start":30.45,"end":33.2},{"text":"“Юу?”","start":33.2,"end":34.45},{"text":"Эдвард түүнээс гуйсан янзтай асуув.","start":34.45,"end":37.25},{"text":"“Чи хорыг нь буцаад сорох гээд үз.","start":37.25,"end":39.9625},{"text":"Шарх нь их цэвэрхэн харагдаж байна.”","start":39.9625,"end":42.625},{"text":"Карлаилийн дуу сонсдох зуур миний толгойнд юм хатган татах мэдрэгдсэн ч би шатаж байсан гарнаасаа болж өвдөлтийг мэдрээгүй юм.","start":42.625,"end":49.776}],"src":"24fb922b0007cd22c6676296.mp3","sha256":"73b91278dc36ddf97f85cb3a36b7d2c691510e7d4fe90a3df901b4e3bb6b21ed","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"94c293220a79f3e10f3d00c5f8fc13e00de4beecfdf0144f4606d5ba41445588","method":"FFmpeg libmp3lame; original provider timing retained"}},"bbe23f590838f43b1a8f5810":{"text":"Алис хүчилсэн дуугаар тэгж болох уу гэв. Карлаил мэдэхгүй ч хурдлах хэрэгтэй гэлээ. Эдвард чадна гэдэгтээ итгэлгүй гэж шаналан эргэлзэв. Карлаил шийдвэр нь зөвхөн түүнийх, тусалж чадахгүй гэв. Эдвард гарнаас нь цус авах бол Карлаил энэ шархыг бөглөх хэрэгтэй гэв. Би өвдөн тийчлэхэд хөл улам өвдөв. Эдвардыг орилон дуудаад нүдээ дахин аниснаа мэдэв. Түүнийг хурдан харахаар нээхийг оролдов. Төгс царай нь намайг шаналан харж байлаа.","duration":29.664,"cues":[{"text":"Алис хүчилсэн дуугаар тэгж болох уу гэв.","start":0.175,"end":3.125},{"text":"Карлаил мэдэхгүй ч хурдлах хэрэгтэй гэлээ.","start":3.125,"end":6.1},{"text":"Эдвард чадна гэдэгтээ итгэлгүй гэж шаналан эргэлзэв.","start":6.1,"end":9.6125},{"text":"Карлаил шийдвэр нь зөвхөн түүнийх, тусалж чадахгүй гэв.","start":9.6125,"end":13.1875},{"text":"Эдвард гарнаас нь цус авах бол Карлаил энэ шархыг бөглөх хэрэгтэй гэв.","start":13.1875,"end":17.5875},{"text":"Би өвдөн тийчлэхэд хөл улам өвдөв.","start":17.5875,"end":20.325},{"text":"Эдвардыг орилон дуудаад нүдээ дахин аниснаа мэдэв.","start":20.325,"end":23.8375},{"text":"Түүнийг хурдан харахаар нээхийг оролдов.","start":23.8375,"end":26.6875},{"text":"Төгс царай нь намайг шаналан харж байлаа.","start":26.6875,"end":29.664}],"src":"bbe23f590838f43b1a8f5810.mp3","sha256":"201a7fd679ddb785ed8e24de3757d9d1dd0b719b8f71bfa4bea2fbe232a40953","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"924928c796a36625a4e8c2ebda10859f71439787ec15c804f24e7c8c6887b4d6","method":"FFmpeg libmp3lame; original provider timing retained"}},"277f6da24c26ed5740394cdc":{"text":"Алис хүчилсэн хоолойгоор тэгж болдог уу гэж асуув. Карлаил мэдэхгүй, гэхдээ хурдлах хэрэгтэй гэв. Эдвард эргэлзэн хийж чадна гэдэгтээ итгэлгүй байгаагаа хэллээ. Гайхамшигтай хоолой нь шанална. Карлаил энэ зөвхөн түүний шийдвэр, өөрөө тусалж чадахгүй гэв. «Чи гарнаас нь цус авах гэж байгаа бол би энэ шархыг бөглөх хэрэгтэй» гэж Карлаил хэлэв. Би өвдөлтөндөө тийчлэхэд хөлний өвчин нэмэгдэв. Эдвардыг орилоод, нүдээ дахин аниснаа мэдлээ. Түүний царайг хурдан харахаар нээхийг оролдож, олж харав. Төгс царай нь над руу шаналан ширтэж байлаа.","duration":35.496,"cues":[{"text":"Алис хүчилсэн хоолойгоор тэгж болдог уу гэж асуув.","start":0.175,"end":3.625},{"text":"Карлаил мэдэхгүй, гэхдээ хурдлах хэрэгтэй гэв.","start":3.625,"end":6.9},{"text":"Эдвард эргэлзэн хийж чадна гэдэгтээ итгэлгүй байгаагаа хэллээ.","start":6.9,"end":10.775},{"text":"Гайхамшигтай хоолой нь шанална.","start":10.775,"end":13.225},{"text":"Карлаил энэ зөвхөн түүний шийдвэр, өөрөө тусалж чадахгүй гэв.","start":13.225,"end":17.1625},{"text":"«Чи гарнаас нь цус авах гэж байгаа бол би энэ шархыг бөглөх хэрэгтэй» гэж Карлаил хэлэв.","start":17.1625,"end":22.2125},{"text":"Би өвдөлтөндөө тийчлэхэд хөлний өвчин нэмэгдэв.","start":22.2125,"end":25.4625},{"text":"Эдвардыг орилоод, нүдээ дахин аниснаа мэдлээ.","start":25.4625,"end":28.75},{"text":"Түүний царайг хурдан харахаар нээхийг оролдож, олж харав.","start":28.75,"end":32.3875},{"text":"Төгс царай нь над руу шаналан ширтэж байлаа.","start":32.3875,"end":35.496}],"src":"277f6da24c26ed5740394cdc.mp3","sha256":"01f9090373133148df56f752a8ba748b67af8cae7d8270849c8e83cc348e3867","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"270d466134b1764f2bbe52d8689d0666523f9916ade7f68846673ac5661336aa","method":"FFmpeg libmp3lame; original provider timing retained"}},"040b31ed8cd6cefa2964d334":{"text":"Карлаил хажууд толгойн шархыг минь эмчилж байв. Тэр Алисаас хөл хөдөлгөхгүй хатуу юм авчрахыг хүсэв. Карлаил Эдвардад одоо хийхгүй бол оройтно гэлээ. Эдвардын эргэлзэл шийдэмгий болж, эрүүгээ чангалав. Түүний хүйтэн хуруу, дараа нь уруул шатах гарт хүрэв. Эхэндээ би бүр их өвдөж, орилоод босох гэв. Хүйтэн гар намайг араас барилаа. Алисын аргадах дуу сонсдоно. Хэн нэгэн хөлийг хөдөлгөхгүй гэж хүнд юм тавьжээ.","duration":28.704,"cues":[{"text":"Карлаил хажууд толгойн шархыг минь эмчилж байв.","start":0.175,"end":3.325},{"text":"Тэр Алисаас хөл хөдөлгөхгүй хатуу юм авчрахыг хүсэв.","start":3.325,"end":6.9},{"text":"Карлаил Эдвардад одоо хийхгүй бол оройтно гэлээ.","start":6.9,"end":10.4125},{"text":"Эдвардын эргэлзэл шийдэмгий болж, эрүүгээ чангалав.","start":10.4125,"end":13.8875},{"text":"Түүний хүйтэн хуруу, дараа нь уруул шатах гарт хүрэв.","start":13.8875,"end":17.2375},{"text":"Эхэндээ би бүр их өвдөж, орилоод босох гэв.","start":17.2375,"end":20.4625},{"text":"Хүйтэн гар намайг араас барилаа.","start":20.4625,"end":22.975},{"text":"Алисын аргадах дуу сонсдоно.","start":22.975,"end":25.4},{"text":"Хэн нэгэн хөлийг хөдөлгөхгүй гэж хүнд юм тавьжээ.","start":25.4,"end":28.704}],"src":"040b31ed8cd6cefa2964d334.mp3","sha256":"aba881fd493c8092b9cf9ddd2d7b4b4edf2367e84a3c57d2d15615739bafeea7","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"d72dd5d7d7d8fb6aca8b4cc840759824358c0c3c6b5b40f48f831dcb6826fe38","method":"FFmpeg libmp3lame; original provider timing retained"}},"157f43ae854b49ad19dffd80":{"text":"“Тэгж болдог юм уу?” Алис хүчилсэн хоолойгоор асуулаа. “Мэдэхгүй,” Карлаил хариулав. “Гэвч бид хурдлах хэрэгтэй.” “Карлаил, би...” Эдвард эргэлзэв. “Би хийж чадна гэдэгтээ итгэлгүй байна.” Түүний гайхамшигтай хоолой нь шаналсан сонсогдож байсан юм. “Чиний л шийдвэр, Эдвард. Би чамд туслаж чадахгүй. Чи хэрэв гарнаас нь цус авах гэж байгаа бол би энэ шархыг нь бөглөх хэрэгтэй.” Би өвдөлтөндөө ийш тийш тийчиж эхлэхэд энэ нь миний хөлний өвчинг улам нэмэгдүүллээ. “Эдвард!” би орлив. Нүдээ дахин анисан байснаа мэдээд түүний царайг хурдан харахын тулд нээхийг оролдож түүнийгээ олж харсан юм. Түүний минь төгс царай над руу шаналан ширтэж байлаа.","duration":42.912,"cues":[{"text":"“Тэгж болдог юм уу?”","start":0.1875,"end":2.125},{"text":"Алис хүчилсэн хоолойгоор асуулаа.","start":2.125,"end":4.8375},{"text":"“Мэдэхгүй,” Карлаил хариулав.","start":4.8375,"end":7.2},{"text":"“Гэвч бид хурдлах хэрэгтэй.”","start":7.2,"end":9.425},{"text":"“Карлаил, би...”","start":9.425,"end":10.275},{"text":"Эдвард эргэлзэв.","start":10.275,"end":12.075},{"text":"“Би хийж чадна гэдэгтээ итгэлгүй байна.”","start":12.075,"end":14.725},{"text":"Түүний гайхамшигтай хоолой нь шаналсан сонсогдож байсан юм.","start":14.725,"end":18.4375},{"text":"“Чиний л шийдвэр, Эдвард.","start":18.4375,"end":19.6875},{"text":"Би чамд туслаж чадахгүй.","start":19.6875,"end":21.8375},{"text":"Чи хэрэв гарнаас нь цус авах гэж байгаа бол би энэ шархыг нь бөглөх хэрэгтэй.”","start":21.8375,"end":26.45},{"text":"Би өвдөлтөндөө ийш тийш тийчиж эхлэхэд энэ нь миний хөлний өвчинг улам нэмэгдүүллээ.","start":26.45,"end":31.35},{"text":"“Эдвард!”","start":31.35,"end":31.85},{"text":"би орлив.","start":31.85,"end":33.3125},{"text":"Нүдээ дахин анисан байснаа мэдээд түүний царайг хурдан харахын тулд нээхийг оролдож түүнийгээ олж харсан юм.","start":33.3125,"end":39.3625},{"text":"Түүний минь төгс царай над руу шаналан ширтэж байлаа.","start":39.3625,"end":42.912}],"src":"157f43ae854b49ad19dffd80.mp3","sha256":"6346eb6a1746f679e609624008f0f98e40f048ea7500de768426a524bb8b9494","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"0c2233698f5994e41833c0eea47a75dd1474986d8568b8f85e5697cfa4547553","method":"FFmpeg libmp3lame; original provider timing retained"}},"65350aa6977f2a5f1fa81b24":{"text":"Карлаил хажууд толгойн шархыг минь эмчилж, Алист хөлийг хөдөлгөхгүй байлгах хатуу юм авчир гэв. Карлаил Эдвардад одоо хийхгүй бол хэт оройтно гэж анхааруулав. Эдвардын нүдний эргэлзэл шийдэмгий байдал болж хувирахад тэр эрүүгээ чангалан бэлдэв. Шатах гар дээр хүйтэн хуруу мэдрэгдэж, тэр тонгойн хүйтэн уруулаа хүргэлээ. Эхэндээ өвдөлт бүр ихсэв. Би орилоод босохыг оролдоход хэн нэгний хүйтэн гар намайг араас минь хойш нь барьж байлаа. Алис хаа нэгтээ намайг аргадах нь сонсдов. Хөлийг хөдөлгөхгүйн тулд хэн нэгэн дээр нь хүнд юм тавьжээ.","duration":33.408,"cues":[{"text":"Карлаил хажууд толгойн шархыг минь эмчилж, Алист хөлийг хөдөлгөхгүй байлгах хатуу юм авчир гэв.","start":0.175,"end":5.5625},{"text":"Карлаил Эдвардад одоо хийхгүй бол хэт оройтно гэж анхааруулав.","start":5.5625,"end":9.575},{"text":"Эдвардын нүдний эргэлзэл шийдэмгий байдал болж хувирахад тэр эрүүгээ чангалан бэлдэв.","start":9.575,"end":14.6375},{"text":"Шатах гар дээр хүйтэн хуруу мэдрэгдэж, тэр тонгойн хүйтэн уруулаа хүргэлээ.","start":14.6375,"end":19.275},{"text":"Эхэндээ өвдөлт бүр ихсэв.","start":19.275,"end":21.6125},{"text":"Би орилоод босохыг оролдоход хэн нэгний хүйтэн гар намайг араас минь хойш нь барьж байлаа.","start":21.6125,"end":26.775},{"text":"Алис хаа нэгтээ намайг аргадах нь сонсдов.","start":26.775,"end":29.7625},{"text":"Хөлийг хөдөлгөхгүйн тулд хэн нэгэн дээр нь хүнд юм тавьжээ.","start":29.7625,"end":33.408}],"src":"65350aa6977f2a5f1fa81b24.mp3","sha256":"cd9f5ba21349e956519860407d46d38860bf48622160c2727ac06657b20e7fc9","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"532a946b57ea3872b5acb870e960f51a9e7b4d3a9ae38b1d7940376b4f967218","method":"FFmpeg libmp3lame; original provider timing retained"}},"e8e511a19a46c432126dd6e2":{"text":"Карлаил ч намайг тэвэрч байв. Гар мэдрэмжгүй болж, тийчих багаслаа. Тархсан гал жижигхэн цэгт хураагдана. Өвдөлт багасах тусам ухаан алдарч, усанд живээд царайг нь харахгүй болохоос айв. Би Эдвардыг аяархан дуудахад бүгд сонсов. Түүнийг энд байна гэв. Би үлдээрэй, намайг битгий орхи гэж гуйв. Тэр «Битгий ай» гэж хүчилсэн ч бага зэрэг бахархсан мэт дуугаар хэлэв. Би санаа алдаж тайвширлаа. Гал унтарч, бүх бие унтахыг хүснэ.","duration":30.24,"cues":[{"text":"Карлаил ч намайг тэвэрч байв.","start":0.175,"end":2.575},{"text":"Гар мэдрэмжгүй болж, тийчих багаслаа.","start":2.575,"end":5.4625},{"text":"Тархсан гал жижигхэн цэгт хураагдана.","start":5.4625,"end":8.175},{"text":"Өвдөлт багасах тусам ухаан алдарч, усанд живээд царайг нь харахгүй болохоос айв.","start":8.175,"end":12.95},{"text":"Би Эдвардыг аяархан дуудахад бүгд сонсов.","start":12.95,"end":16.0125},{"text":"Түүнийг энд байна гэв.","start":16.0125,"end":18.0875},{"text":"Би үлдээрэй, намайг битгий орхи гэж гуйв.","start":18.0875,"end":21.05},{"text":"Тэр «Битгий ай» гэж хүчилсэн ч бага зэрэг бахархсан мэт дуугаар хэлэв.","start":21.05,"end":25.2125},{"text":"Би санаа алдаж тайвширлаа.","start":25.2125,"end":27.55},{"text":"Гал унтарч, бүх бие унтахыг хүснэ.","start":27.55,"end":30.24}],"src":"e8e511a19a46c432126dd6e2.mp3","sha256":"a61fa4dee9e75b232ec415411125772fac41fe909a0e5c31f9a6f5adcf1d0cb9","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"740b5632cfbba05b54b1ea9dc8e2b33edc7d573abbb630f523a367bc199a69c5","method":"FFmpeg libmp3lame; original provider timing retained"}},"8e152034bed91ea714eebd68":{"text":"Карлаил бас намайг тэвэрч суулаа. Гар мэдрэмжээ алдаж эхлэхэд тийчих багасав. Тархсан гал нэг жижиг цэгт төвлөрнө. Өвдөлт багасах тусам ухаан алдарч, дахин усанд живэн түүний царайг харахгүй болохоос айлаа. Би Эдвардыг аяархан хэлсэн ч бүгд сонсов. Түүнийг яг энд байна гэв. «Үлдээрэй, Эдвард. Намайг битгий орхиорой» гэж би түүнээс гуйлаа. «Битгий ай» гэх хоолой нь хүчилсэн ч өөрөөрөө бага зэрэг бахархсан мэт сонсдов. Би санаа алдан тайвширлаа. Гал бүрэн унтарч, бүх бие минь нойр шаардаж байв.","duration":33.744,"cues":[{"text":"Карлаил бас намайг тэвэрч суулаа.","start":0.175,"end":2.8375},{"text":"Гар мэдрэмжээ алдаж эхлэхэд тийчих багасав.","start":2.8375,"end":5.9375},{"text":"Тархсан гал нэг жижиг цэгт төвлөрнө.","start":5.9375,"end":8.6625},{"text":"Өвдөлт багасах тусам ухаан алдарч, дахин усанд живэн түүний царайг харахгүй болохоос айлаа.","start":8.6625,"end":14.1125},{"text":"Би Эдвардыг аяархан хэлсэн ч бүгд сонсов.","start":14.1125,"end":17.1875},{"text":"Түүнийг яг энд байна гэв.","start":17.1875,"end":19.425},{"text":"«Үлдээрэй, Эдвард.","start":19.425,"end":20.425},{"text":"Намайг битгий орхиорой» гэж би түүнээс гуйлаа.","start":20.425,"end":23.525},{"text":"«Битгий ай» гэх хоолой нь хүчилсэн ч өөрөөрөө бага зэрэг бахархсан мэт сонсдов.","start":23.525,"end":28.0875},{"text":"Би санаа алдан тайвширлаа.","start":28.0875,"end":30.4125},{"text":"Гал бүрэн унтарч, бүх бие минь нойр шаардаж байв.","start":30.4125,"end":33.744}],"src":"8e152034bed91ea714eebd68.mp3","sha256":"6e339e8926cb49182c4a1957350c91cf45d4995c54da160ddfd3d4f821fb1a2c","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"30fb7d9fe8dbf0644aefef6cb15a4dd704c27cac4987d648355e8dcf7899fb87","method":"FFmpeg libmp3lame; original provider timing retained"}},"71aecd6faa51cf110ef3634e":{"text":"“Алис, хөлийг нь хөдлөхгүй байлгах нэг хатуу юм аваад ир!” Карлаил миний толгойны шархыг эмчлэн хажууд сууж байлаа. “Эдвард, чи одоо л хийхгүй бол дэндүү оройтно.” Эдвардийн нүдэн дэх эргэлзэл гэнэт өөрчлөгдөн тэмүүлэл болон хувирахыг би харж хэвтлээ. Тэр эрүүгээ чангалан бэлдэв. Миний шатаж байсан гаран дээр түүний хүйтэн хуруунууд мэдрэгдэн Эдвард тонгойн хүйтэн уруулаа гаранд минь хүргэлээ. Анхандаа өвдөлт бүр ч их доройтсон юм. Би орлин босохыг оролдтол хэн нэгний хүйтэн гар намайг хойш нь барьж байлаа. Алисийн хоолой хаа нэгтээ намайг аргадах сонсдов. Хэн нэгэн миний хөлийг хөдлөхгүйн тулд дээрээс нь хүнд юм тавьсан байлаа.","duration":40.128,"cues":[{"text":"“Алис, хөлийг нь хөдлөхгүй байлгах нэг хатуу юм аваад ир!”","start":0.175,"end":3.825},{"text":"Карлаил миний толгойны шархыг эмчлэн хажууд сууж байлаа.","start":3.825,"end":7.6},{"text":"“Эдвард, чи одоо л хийхгүй бол дэндүү оройтно.”","start":7.6,"end":10.775},{"text":"Эдвардийн нүдэн дэх эргэлзэл гэнэт өөрчлөгдөн тэмүүлэл болон хувирахыг би харж хэвтлээ.","start":10.775,"end":16.1},{"text":"Тэр эрүүгээ чангалан бэлдэв.","start":16.1,"end":18.4625},{"text":"Миний шатаж байсан гаран дээр түүний хүйтэн хуруунууд мэдрэгдэн Эдвард тонгойн хүйтэн уруулаа гаранд минь хүргэлээ.","start":18.4625,"end":24.7625},{"text":"Анхандаа өвдөлт бүр ч их доройтсон юм.","start":24.7625,"end":27.75},{"text":"Би орлин босохыг оролдтол хэн нэгний хүйтэн гар намайг хойш нь барьж байлаа.","start":27.75,"end":32.4},{"text":"Алисийн хоолой хаа нэгтээ намайг аргадах сонсдов.","start":32.4,"end":35.725},{"text":"Хэн нэгэн миний хөлийг хөдлөхгүйн тулд дээрээс нь хүнд юм тавьсан байлаа.","start":35.725,"end":40.128}],"src":"71aecd6faa51cf110ef3634e.mp3","sha256":"d8d485775745d397d1428b3bf36929902ddf2d9dd655a8419429f68b0cb6635c","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"5696511798d2ed7645b88b6e16bd9636bc3527b24e348e3bf094f1067c913dfa","method":"FFmpeg libmp3lame; original provider timing retained"}},"6dcf61058d69cecea19717a9":{"text":"Карлаил бүх хор гарсан уу гэж асуув. Эдвард цус цэвэр болсон шиг байна, Карлаилийн хийсэн морфин амтагдсан гэв. Карлаил намайг дуудахад би арай хариулав. Гал унтарсан уу гэхэд тийм гэж санаа алдаад Эдвардад баярлалаа гэв. Тэр хайртай гэв. Би мэднэ гэж ядарч хариулахад санаа амарсан инээдийг нь сонсов. Энэ миний дуртай дуу. Карлаил дахин дуудахад унтмаар тул хөмсөг зангидав. Ээж хаана байна гэхэд Флоридад, тэр намайг хуурсан гэж хэлэв.","duration":30.144,"cues":[{"text":"Карлаил бүх хор гарсан уу гэж асуув.","start":0.175,"end":2.9625},{"text":"Эдвард цус цэвэр болсон шиг байна, Карлаилийн хийсэн морфин амтагдсан гэв.","start":2.9625,"end":7.675},{"text":"Карлаил намайг дуудахад би арай хариулав.","start":7.675,"end":10.625},{"text":"Гал унтарсан уу гэхэд тийм гэж санаа алдаад Эдвардад баярлалаа гэв.","start":10.625,"end":14.8375},{"text":"Тэр хайртай гэв.","start":14.8375,"end":16.6375},{"text":"Би мэднэ гэж ядарч хариулахад санаа амарсан инээдийг нь сонсов.","start":16.6375,"end":20.6625},{"text":"Энэ миний дуртай дуу.","start":20.6625,"end":22.7},{"text":"Карлаил дахин дуудахад унтмаар тул хөмсөг зангидав.","start":22.7,"end":26.25},{"text":"Ээж хаана байна гэхэд Флоридад, тэр намайг хуурсан гэж хэлэв.","start":26.25,"end":30.144}],"src":"6dcf61058d69cecea19717a9.mp3","sha256":"1a5b3c63073669b4c2b0ec7a20cb9abe1a882b3f79e471143fef1298997b64ce","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"af3aea2b6adacc3001d7b197e13d0eb30abc26f26d87b22c8c283ee051e76b87","method":"FFmpeg libmp3lame; original provider timing retained"}},"fefb03c25726e8e25724d385":{"text":"Карлаил бас намайг тэврэн сууж байв. Эцэст нь миний гар мэдрэмжээ алдаж эхлэхэд миний тийчих ч багассан юм. Тархсан байсан гал буцан нэг л жижигхэн цэгт төвлөрч байлаа. Өвдөлт багасах тусам миний ухаан алдагдаж байв. Би дахин тэр усанд живэн түүний царайг харахгүй гэдгээсээ айж байсан юм. “Эдвард,” би аяархан хэлсэн ч бүгд намайг сонссон юм. “Тэр яг энд байна, Белла,” “Үлдээрэй, Эдвард. Намайг битгий орхиорой...” “Битгий ай.” Тэр маань хоолойгоо хүчилсэн сонсогдож байсан ч бас өөрөөрөө бага зэрэг бахархаж буй мэт сонсдсон юм. Би санаа алдан сэтгэл амарлаа. Гал бүрэн унтраагдаж бүхэл бие минь надаас нойр шаардаж байлаа.","duration":39.408,"cues":[{"text":"Карлаил бас намайг тэврэн сууж байв.","start":0.175,"end":2.9375},{"text":"Эцэст нь миний гар мэдрэмжээ алдаж эхлэхэд миний тийчих ч багассан юм.","start":2.9375,"end":7.2375},{"text":"Тархсан байсан гал буцан нэг л жижигхэн цэгт төвлөрч байлаа.","start":7.2375,"end":11.125},{"text":"Өвдөлт багасах тусам миний ухаан алдагдаж байв.","start":11.125,"end":14.4},{"text":"Би дахин тэр усанд живэн түүний царайг харахгүй гэдгээсээ айж байсан юм.","start":14.4,"end":18.775},{"text":"“Эдвард,” би аяархан хэлсэн ч бүгд намайг сонссон юм.","start":18.775,"end":22.3},{"text":"“Тэр яг энд байна, Белла,” “Үлдээрэй, Эдвард.","start":22.3,"end":24.65},{"text":"Намайг битгий орхиорой...”","start":24.65,"end":25.7875},{"text":"“Битгий ай.”","start":25.7875,"end":27.1625},{"text":"Тэр маань хоолойгоо хүчилсэн сонсогдож байсан ч бас өөрөөрөө бага зэрэг бахархаж буй мэт сонсдсон юм.","start":27.1625,"end":32.9875},{"text":"Би санаа алдан сэтгэл амарлаа.","start":32.9875,"end":35.4625},{"text":"Гал бүрэн унтраагдаж бүхэл бие минь надаас нойр шаардаж байлаа.","start":35.4625,"end":39.408}],"src":"fefb03c25726e8e25724d385.mp3","sha256":"9f9893b3e301c0e4c8dbe1acc92b91e7d839a0c006c06c8cca8ddc5a4076ba79","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"cdd0f41472c6037de18b6e6a7c7750b60fc9637f6a5b2987f7fbf12cec1db963","method":"FFmpeg libmp3lame; original provider timing retained"}},"d7d7514172c46dff47aa4abf":{"text":"Карлаил өрөөний хаа нэгтээгээс бүгд гарсан уу гэж асуув. Эдвард цус цэвэр болсон шиг байна, Карлаилийн хийсэн морфин амтагдсан гэж аяархан хариулав. Карлаил намайг дуудахад хариулахыг оролдов. Гал унтарсан уу гэхэд би тийм гэж санаа алдаад Эдвардад баярлалаа гэв. Тэр хайртай гэхэд мэднэ гэж ядарсан хоолойгоор хариулав. Түүний санаа амарсан инээд, дэлхийн хамгийн дуртай дуугаа сонслоо. Карлаил дахин дуудахад унтмаар байсан тул хөмсгөө зангидав. Ээж хаана байгааг асуув. «Флоридад. Тэр намайг хуурсан байсан» гэж санаа алдав.","duration":33.984,"cues":[{"text":"Карлаил өрөөний хаа нэгтээгээс бүгд гарсан уу гэж асуув.","start":0.175,"end":3.85},{"text":"Эдвард цус цэвэр болсон шиг байна, Карлаилийн хийсэн морфин амтагдсан гэж аяархан хариулав.","start":3.85,"end":9.325},{"text":"Карлаил намайг дуудахад хариулахыг оролдов.","start":9.325,"end":12.3375},{"text":"Гал унтарсан уу гэхэд би тийм гэж санаа алдаад Эдвардад баярлалаа гэв.","start":12.3375,"end":16.7},{"text":"Тэр хайртай гэхэд мэднэ гэж ядарсан хоолойгоор хариулав.","start":16.7,"end":20.3375},{"text":"Түүний санаа амарсан инээд, дэлхийн хамгийн дуртай дуугаа сонслоо.","start":20.3375,"end":24.475},{"text":"Карлаил дахин дуудахад унтмаар байсан тул хөмсгөө зангидав.","start":24.475,"end":28.3375},{"text":"Ээж хаана байгааг асуув.","start":28.3375,"end":30.475},{"text":"«Флоридад.","start":30.475,"end":31.05},{"text":"Тэр намайг хуурсан байсан» гэж санаа алдав.","start":31.05,"end":33.984}],"src":"d7d7514172c46dff47aa4abf.mp3","sha256":"ca6c0fa7a2386e122be3d9f40ebd7515e727271fdb5482cee106d4de624c19fa","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"e9719b74697414133db5f38e1140b6b90581622618e0eda4e8bba90adbaf147d","method":"FFmpeg libmp3lame; original provider timing retained"}},"8294023376969352f5dfccda":{"text":"“Бүгд гарчихсан уу?” Карлаил өрөөний хаа нэгтээгээс асуув. “Цус нь цэвэрхэн болчих шиг боллоо,” Эдвард аяархнаар хариуллаа. “Таны хийсэн морфин амтагдаж байсан.” “Белла,” Карлаил над руу дуудав. Би хариу өгөхийг оролдлоо. “Мммм?” “Гал унтарсан уу?” “Аанхан,” би санаа алдав. “Баярлалаа, Эдвард.” “Би чамд хайртай,” тэр хариулав. “Мэднэ ээ,” би ядарсан хоолойгоор хариулав. Би энэ хорвоо дээрх өөрийн хамгийн дуртай дуу болох Эдвардийн санаа нь амран инээж буйг сонсов. “Белла?” Карлаил дахин дуудлаа . Би унтахыг хүсэж байсан тул хөмсгөө зангидав. “Юу?” “Ээж чинь хаана байгаа юм бэ?” “Флоридад,” би санаа алдан хэлэв. “Тэр намайг хуурсан байсан.","duration":49.728,"cues":[{"text":"“Бүгд гарчихсан уу?”","start":0.175,"end":2.0},{"text":"Карлаил өрөөний хаа нэгтээгээс асуув.","start":2.0,"end":4.7875},{"text":"“Цус нь цэвэрхэн болчих шиг боллоо,” Эдвард аяархнаар хариуллаа.","start":4.7875,"end":8.725},{"text":"“Таны хийсэн морфин амтагдаж байсан.”","start":8.725,"end":11.4875},{"text":"“Белла,” Карлаил над руу дуудав.","start":11.4875,"end":14.0125},{"text":"Би хариу өгөхийг оролдлоо.","start":14.0125,"end":16.325},{"text":"“Мммм?”","start":16.325,"end":17.75},{"text":"“Гал унтарсан уу?”","start":17.75,"end":19.4875},{"text":"“Аанхан,” би санаа алдав.","start":19.4875,"end":21.75},{"text":"“Баярлалаа, Эдвард.”","start":21.75,"end":23.7375},{"text":"“Би чамд хайртай,” тэр хариулав.","start":23.7375,"end":26.1375},{"text":"“Мэднэ ээ,” би ядарсан хоолойгоор хариулав.","start":26.1375,"end":29.1625},{"text":"Би энэ хорвоо дээрх өөрийн хамгийн дуртай дуу болох Эдвардийн санаа нь амран инээж буйг сонсов.","start":29.1625,"end":34.6375},{"text":"“Белла?”","start":34.6375,"end":36.0625},{"text":"Карлаил дахин дуудлаа .","start":36.0625,"end":38.25},{"text":"Би унтахыг хүсэж байсан тул хөмсгөө зангидав.","start":38.25,"end":41.3625},{"text":"“Юу?”","start":41.3625,"end":42.6125},{"text":"“Ээж чинь хаана байгаа юм бэ?”","start":42.6125,"end":44.9125},{"text":"“Флоридад,” би санаа алдан хэлэв.","start":44.9125,"end":47.525},{"text":"“Тэр намайг хуурсан байсан.","start":47.525,"end":49.728}],"src":"8294023376969352f5dfccda.mp3","sha256":"9386bd61184db7f18e6501f88f348363b80657e6c5b17aace0590ff442588861","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"6d1fd7b2d7402b97a8013d58e7669e073f526dfd677d7b52bd3ffbc31b5c4def","method":"FFmpeg libmp3lame; original provider timing retained"}},"9ce9d86d90609baa01e39f9f":{"text":"Тэр манай гэрийн бичлэгийг олоод үзсэн гэж би хэлэв. Ууртай ярих гэсэн ч ядарснаас мэдэгдэхгүй байлаа. Гэнэт чухал юм санаад сэргэх гэж хичээв. Нүдээ нээхээр оролдон Алисыг дуудаж «Бичлэг… тэр чамайг таньж байсан, хаанаас ирснийг чинь мэдэж байна» гэв. Хурдан ярих гэсэн ч хоолой дийлэхгүй. Бензин үнэртэж байгааг хэллээ. Карлаил намайг хөдөлгөх хэрэгтэй гэв. Би унтмаар гэж эсэргүүцэв. Эдвард унт, би тэврээд явъя гэв. Цээжиндээ наан өргөхөд өвчин арилсан мэт санагдав.","duration":32.568,"cues":[{"text":"Тэр манай гэрийн бичлэгийг олоод үзсэн гэж би хэлэв.","start":0.175,"end":3.6},{"text":"Ууртай ярих гэсэн ч ядарснаас мэдэгдэхгүй байлаа.","start":3.6,"end":7.0875},{"text":"Гэнэт чухал юм санаад сэргэх гэж хичээв.","start":7.0875,"end":10.0375},{"text":"Нүдээ нээхээр оролдон Алисыг дуудаж «Бичлэг…","start":10.0375,"end":12.15},{"text":"тэр чамайг таньж байсан, хаанаас ирснийг чинь мэдэж байна» гэв.","start":12.15,"end":15.95},{"text":"Хурдан ярих гэсэн ч хоолой дийлэхгүй.","start":15.95,"end":18.8625},{"text":"Бензин үнэртэж байгааг хэллээ.","start":18.8625,"end":21.3125},{"text":"Карлаил намайг хөдөлгөх хэрэгтэй гэв.","start":21.3125,"end":24.025},{"text":"Би унтмаар гэж эсэргүүцэв.","start":24.025,"end":26.3375},{"text":"Эдвард унт, би тэврээд явъя гэв.","start":26.3375,"end":29.1},{"text":"Цээжиндээ наан өргөхөд өвчин арилсан мэт санагдав.","start":29.1,"end":32.568}],"src":"9ce9d86d90609baa01e39f9f.mp3","sha256":"31d56a763d4fc22d765b02096832c64c8d7314582ad662ae475c30e6f6879283","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"cd9100ce1072aa1b1220eac35934dc6138bfc018b8a473b0e5b14b72f72a743e","method":"FFmpeg libmp3lame; original provider timing retained"}},"b5be3f0aec09aca73111f36b":{"text":"Тэр манай гэрийн бичлэгүүдийг олоод үзсэн байжээ гэв. Би ууртай хэлэхийг хичээсэн ч ядарснаас бараг мэдэгдсэнгүй. Гэнэт чухал зүйл санаад өөрийгөө сэрээхийг оролдов. Нүдээ нээхээр хичээн Алисыг дуудлаа. «Бичлэг… тэр чамайг таньж байсан. Чиний хаанаас ирснийг мэдэж байна лээ.» Би хурдан ярихыг хүссэн ч хоолой дийлэхгүй байв. Бензин үнэртэж байгааг нэмэв. Карлаил намайг хөдөлгөх хэрэгтэй гэв. Би унтмаар гэж эсэргүүцлээ. Эдвард «Унт, хайрт минь. Би тэврээд явъя» гэж тайвшруулав. Тэр цээжиндээ наан өргөж явахад бүх өвчин алга болсон мэт санагдав.","duration":38.52,"cues":[{"text":"Тэр манай гэрийн бичлэгүүдийг олоод үзсэн байжээ гэв.","start":0.175,"end":3.6875},{"text":"Би ууртай хэлэхийг хичээсэн ч ядарснаас бараг мэдэгдсэнгүй.","start":3.6875,"end":7.5125},{"text":"Гэнэт чухал зүйл санаад өөрийгөө сэрээхийг оролдов.","start":7.5125,"end":10.9125},{"text":"Нүдээ нээхээр хичээн Алисыг дуудлаа.","start":10.9125,"end":13.675},{"text":"«Бичлэг…","start":13.675,"end":14.0125},{"text":"тэр чамайг таньж байсан.","start":14.0125,"end":16.0875},{"text":"Чиний хаанаас ирснийг мэдэж байна лээ.»","start":16.0875,"end":18.8375},{"text":"Би хурдан ярихыг хүссэн ч хоолой дийлэхгүй байв.","start":18.8375,"end":22.075},{"text":"Бензин үнэртэж байгааг нэмэв.","start":22.075,"end":24.5},{"text":"Карлаил намайг хөдөлгөх хэрэгтэй гэв.","start":24.5,"end":27.2125},{"text":"Би унтмаар гэж эсэргүүцлээ.","start":27.2125,"end":29.5875},{"text":"Эдвард «Унт, хайрт минь.","start":29.5875,"end":31.725},{"text":"Би тэврээд явъя» гэж тайвшруулав.","start":31.725,"end":34.2625},{"text":"Тэр цээжиндээ наан өргөж явахад бүх өвчин алга болсон мэт санагдав.","start":34.2625,"end":38.52}],"src":"b5be3f0aec09aca73111f36b.mp3","sha256":"89960511f5761e013e68121c2630cba313559198ed99a0a26d2f6f4488d52220","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"ab9915edd06583e740cbfeb7c37453ab8012df8e70caceef47bf7c41177a7909","method":"FFmpeg libmp3lame; original provider timing retained"}},"2c4e5fc9dab1053934405e4d":{"text":"Манай гэрийн бичлэгүүдийг олоод үзчихсэн байсан.” Би ууртай хэлэхийг оролдож байсан ч их ядарсан тул бараг мэдэгдэхгүй байв. Гэнэт би нэг чухал юм санан өөрийгөө сэрээхийг оролдов. “Алис,” би нүдээ нээхийг оролдон дуудлаа. “Алис, бичлэг – тэр чамайг таньж байсан. Чиний хаанаас ирснийг мэдэж байна лээ.” Би хурдан ярихыг оролдож байсан ч хоолой минь дийлэхгүй байсан юм. “Бензин үнэртээд байна,” би нэмж хэлэв. “Түүнийг хөдөлгөх хэрэгтэй,” Карлаил удирдав. “Үгүй ээ, би унтмаар байна,” би эсэргүүцэв. “Унт, хайрт минь. Би чамайг тэврээд явъя,” Эдвард намайг тайвшруулан хэллээ. Тэр намайг цээжиндээ наан өргөн явахад хамаг өвчин байхгүй болсон юм шиг санагдаж эхлэв.","duration":44.16,"cues":[{"text":"Манай гэрийн бичлэгүүдийг олоод үзчихсэн байсан.”","start":0.1625,"end":3.4125},{"text":"Би ууртай хэлэхийг оролдож байсан ч их ядарсан тул бараг мэдэгдэхгүй байв.","start":3.4125,"end":7.925},{"text":"Гэнэт би нэг чухал юм санан өөрийгөө сэрээхийг оролдов.","start":7.925,"end":11.6375},{"text":"“Алис,” би нүдээ нээхийг оролдон дуудлаа.","start":11.6375,"end":14.6625},{"text":"“Алис, бичлэг – тэр чамайг таньж байсан.","start":14.6625,"end":17.65},{"text":"Чиний хаанаас ирснийг мэдэж байна лээ.”","start":17.65,"end":20.4},{"text":"Би хурдан ярихыг оролдож байсан ч хоолой минь дийлэхгүй байсан юм.","start":20.4,"end":24.4125},{"text":"“Бензин үнэртээд байна,” би нэмж хэлэв.","start":24.4125,"end":27.25},{"text":"“Түүнийг хөдөлгөх хэрэгтэй,” Карлаил удирдав.","start":27.25,"end":30.35},{"text":"“Үгүй ээ, би унтмаар байна,” би эсэргүүцэв.","start":30.35,"end":33.4125},{"text":"“Унт, хайрт минь.","start":33.4125,"end":35.2125},{"text":"Би чамайг тэврээд явъя,” Эдвард намайг тайвшруулан хэллээ.","start":35.2125,"end":39.025},{"text":"Тэр намайг цээжиндээ наан өргөн явахад хамаг өвчин байхгүй болсон юм шиг санагдаж эхлэв.","start":39.025,"end":44.16}],"src":"2c4e5fc9dab1053934405e4d.mp3","sha256":"cb8f61b5d9ecc35898e031727fbf1c17bacb1a3461a04d9d20981c1e0d3fc274","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"2088e6b0f8618b03c0964434aa549a79213f46292bfb2f1913c39a2b9bf39a8e","method":"FFmpeg libmp3lame; original provider timing retained"}},"45a40273b6b9205840acc909":{"text":"«Унт, Белла» гэдэг нь миний сонссон хамгийн сүүлчийн үг байлаа.","duration":4.032,"cues":[{"text":"«Унт, Белла» гэдэг нь миний сонссон хамгийн сүүлчийн үг байлаа.","start":0.175,"end":4.032}],"src":"45a40273b6b9205840acc909.mp3","sha256":"9c412561c9bd67ac75c32c3141d9f2f4674f11c29724be34e33b1fa976971853","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"7bb6e5682dfafe29699be936386267229024577e9a3aebd5ab335960587d7c0a","method":"FFmpeg libmp3lame; original provider timing retained"}},"65bfef6fe4831818c7814c6c":{"text":"Миний хамгийн сүүлд сонссон үг «Унт, Белла» байлаа.","duration":3.648,"cues":[{"text":"Миний хамгийн сүүлд сонссон үг «Унт, Белла» байлаа.","start":0.1625,"end":3.648}],"src":"65bfef6fe4831818c7814c6c.mp3","sha256":"3bc8097a48ad6af2cefc221c3897c5d2d90c6128c277c00539debf07f8ce5e78","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"97a358c67b2ba0e475b836228553fa168afcda9115e64998190cb41a23020b42","method":"FFmpeg libmp3lame; original provider timing retained"}},"a4421a184e90d36132ec2581":{"text":"“Унт, Белла” миний сонссон хамгийн сүүлийн үг байсан юм.","duration":3.768,"cues":[{"text":"“Унт, Белла” миний сонссон хамгийн сүүлийн үг байсан юм.","start":0.175,"end":3.768}],"src":"a4421a184e90d36132ec2581.mp3","sha256":"6b4de6a44d2ceb713ebeb2a50add55f37cacac2ad5fec43588694372e01042c5","boundaryMode":"WordBoundary","metadataTextCoverage":true,"encoding":{"codec":"MP3","sampleRateHz":24000,"channels":1,"bitRateKbps":24,"sourceSha256":"a3302da2db7384c2d3465c4af3069678ed1950edc191a342ba649936f0433d6b","method":"FFmpeg libmp3lame; original provider timing retained"}}}};
